INSERT INTO "communities" ("id","square_footage_range","name","slug","town","published","address","map_coordinates","latitude","longitude","lat_long","master_planned","coming_soon","price_from","bed_count","bath_count","description","amenities","education_rich","design_copy_rich","exterior_construction_copy_rich","interior_construction_copy_rich","conservation_landscape_copy_rich","energy_package_copy_rich","kitchen_features_copy_rich","bath_features_copy_rich","esperanza_difference_copy_rich","gas_details_rich","internet_details","water_details","electric_details_rich","security_details","directions","featured_image_url","featured_image_alt","secondary_image_url","secondary_image_alt","photo_gallery_image_url","photo_gallery_image_alt","description_image_url","community_logo_url","community_logo_alt","features_download_url","resources_download_url","featured_video","office_phone","office_hours","schedule_visit","lending","mine_link","community_map_embed","incentive","floor_plan_plaintext","hoa_links_json","city_id","created_at","updated_at","custom_fields","brochure_pdf_url") VALUES('rec1US9Cbl24sWY69',NULL,'Vista Verde','vista-verde','Laredo',1,'1891 Burns Boulevard','https://www.google.com/maps?q=27.4350270,-99.4512076',27.435027,-99.4512076,'27.4350270,-99.4512076',0,1,226990,NULL,NULL,'Vista Verde is a vibrant new community coming soon to Laredo, Texas. Featuring energy-efficient homes with modern, open-concept designs, Vista Verde is thoughtfully built for comfort, quality, and everyday living. Conveniently located near the Buena Vista Sports Complex and surrounded by shopping, dining, and schools, Vista Verde brings together lifestyle, location, and value. Join the VIP list to receive early updates on pricing, floor plans, and more before the public release.',NULL,replace('- Edinburg Independent School District\n- Crawford Elementary\n- Harwell Middle School\n- Edinburg North High School\n- The University of Texas Rio Grande Valley\n','\n',char(10)),replace('- Design Consultation and On-Site Design Center\n- Large Selection of Choices, Colors and Finishes\n- Award Winning Architectural Designs\n','\n',char(10)),replace('- Engineered Foundation and Windstorm Plans\n- 100% Stucco Exterior\n- Screens on all Operable Windows\n- Underground Utilities\n- Exterior Paint—Sherwin Williams\n- Bora-Care with Mold-Care pest treatment\n- James Hardie Fiber Cement Soffits and Fascia (50 yr warranty)\n- 2-Car Garage\n','\n',char(10)),replace('- Smoke Detectors w/ Battery Backup\n- 9 ft ceilings—First Floor per plan\n- Ceramic Tile in all Standard Areas -\n- (1st Floor Common/Living, Bathrooms, Utility, Casita)\n- Carpet in all Non-Standard Areas -\n- (Bedrooms, Study, Loft, Gameroom, Media, 2nd Floor Common/Living)\n- Stained Oak Staircase with Painted Risers\n- Stained Oak Handrail with Painted Balusters\n- Interior Paint—Sherwin Williams\n- Liftmaster Garage Door Opener\n- Upgraded Lighting Package by Illuminations\n- Molded Panel Interior Doors\n- CAT6 in Master and Living Room\n- RG6 in all rooms\n- Rounded Corners Throughout Home\n- Ceiling Fans in Master Bedroom and Family Room\n- All other Bedrooms Blocked and Wired for Fans\n- Custom Built Staircase with Pine Spindles\n- Textured Walls\n- Handcrafted Wood Cabinets\n- Shoe mold included with baseboard in all non-carpeted areas (excluding concrete areas)\n','\n',char(10)),replace('- Fully Sodded Front & Side Yards to Fence—Carpet Grass\n- 2 Trees & 11 Shrubs in front yard- Upgrades Available\n- 6’ Rear Yard Sealed Wood Fence all around\n- Full Front and Backyard Irrigation System\n- 6 ft Rear Fence\n- 4 ft front and side wrought iron fence (except front-entry homes)\n','\n',char(10)),replace('- Energy Star Certified Home\n- Natural Gas Service to Each Home\n- Navien NPE Tankless Water Heater\n- LowE Insulated Double Pane Windows with Argon Gas\n- Spray Foam Insulation\n- Lennox Variable-Speed Air Handler/Humidity Control\n- High Efficiency Electric 15.2 SEER2 Air Conditioning\n- R-6 Insulated Air Conditioning Box Duct Work\n- Poly Sealant around Windows, Doors and Plates\n- Lifetime Owens Corning TrueDef Roof Shingles\n- Insulated Fiberglass Front Door\n- LED Lighting\n','\n',char(10)),replace('- MSI Granite Countertops\n- 20 gauge Stainless Steel Undermount Sink\n- ½ hp Badger Garbage Disposal\n- 36” Raised Panel Ash Cabinets for 9ft Ceilings/42” for 10 ft Ceilings\n- Kitchen Backsplash—6x6 Ceramic Backsplash\n- Moen Faucet\n- GE Energy Star Appliances—Dishwasher,\n- 30” Electric Range, and Combo Micro/Vent Hood\n','\n',char(10)),replace('- Bath Tile to Ceiling for Master Bath\n- Glassed Shower Enclosure; Soaking Tub\n- Secondary Baths - Wall Tile 8'' with Steel Tub\n- 36” Base Vanity Cabinets in Master Bath & 30” in Second Bath\n- MSI Granite Countertops\n- Moen Fixtures\n- Elongated Toilets\n- Schluter Edge Profile for all Bath Tile in Brushed Aluminum\n','\n',char(10)),replace('- 1-2-10 Major Structural Warranty\n- Pre-Construction Orientation\n- Pre-Drywall Meeting\n- Pre-Closing Inspection\n- Post Move- In Meeting\n- Online Interactive Customer Portal\n','\n',char(10)),replace('**City of Laredo** <https://laredoutilities.com/>\n956-727-6402\n','\n',char(10)),NULL,NULL,replace('**AEP** <https://www.aeptexas.com/savings/>\n866-223-8508\n','\n',char(10)),NULL,NULL,'https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/communities/rec1US9Cbl24sWY69/FIPsCiHhv2XEps62Y-62GY6qjtZsyaLN4KsA3ejigLI',NULL,'https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/communities/rec1US9Cbl24sWY69/aAECKrpFuC0N-jgD11ihLDchi5I4Ua3l0MJOCTsiTc8',NULL,'https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/communities/rec1US9Cbl24sWY69/POOjLxe2dxyd2VZaws663n1czNQvUCbSJTmPSom0Kfk',NULL,'https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/communities/rec1US9Cbl24sWY69/0_UuNQXI-Nxo-ei6rjuferepU5gbxghepcL4y7Pj8JQ','https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/communities/rec1US9Cbl24sWY69/DZJVUKFDo5z2ZkFtG70rJlFOB5YtzbEopeScyG5b6FQ',NULL,'https://pub-9c9bfee574a5