INSERT INTO "communities" ("id","square_footage_range","name","slug","town","published","address","map_coordinates","latitude","longitude","lat_long","master_planned","coming_soon","price_from","bed_count","bath_count","description","amenities","education_rich","design_copy_rich","exterior_construction_copy_rich","interior_construction_copy_rich","conservation_landscape_copy_rich","energy_package_copy_rich","kitchen_features_copy_rich","bath_features_copy_rich","esperanza_difference_copy_rich","gas_details_rich","internet_details","water_details","electric_details_rich","security_details","directions","featured_image_url","featured_image_alt","secondary_image_url","secondary_image_alt","photo_gallery_image_url","photo_gallery_image_alt","description_image_url","community_logo_url","community_logo_alt","features_download_url","resources_download_url","featured_video","office_phone","office_hours","schedule_visit","lending","mine_link","community_map_embed","incentive","floor_plan_plaintext","hoa_links_json","city_id","created_at","updated_at","custom_fields","brochure_pdf_url") VALUES('rectUf4cPjgY0GEcZ',NULL,'Bentsen Palm Master Planned Community','bentsen-palm-master-planned-community','Mission',1,'2105 Tanager Lane','https://maps.google.com/maps?q=26.1883636,-98.3778773',26.1883636,-98.3778773,'  26.1883636,-98.3778773',1,0,NULL,NULL,NULL,replace('Bentsen Palm is 2,600 acres of Texas paradise. This unique Master-Planned Conservation Community of new homes for sale in Mission, TX brings together 3 neighborhoods in an eco-friendly environment designed to promote and protect the beauty of nature.\nThe biggest attraction at Bentsen Palm is the feeling of “family.” Bentsen Palm is a close-knit community where friendships start, grow, and last a lifetime. We’re invested in making this a place everyone loves to call home.\nWith a fantastic location within walking distance from 3,000 acres of state, federal and city parks – and minutes from McAllen – Bentsen Palm has something for everyone.','\n',char(10)),replace('- Over 10 miles of hike and bike trails\n- Playgrounds for multiple age groups\n- Proximity to World Birding Center\n- National Butterfly Center\n- Bentsen-Rio Grande Valley State Park\n- Community park with picnic shelters\n- Pond with pier\n- Lighted baseball/softball fields\n- Basketball courts\n- Tennis courts\n- Shuffle board courts\n','\n',char(10)),replace('- La Joya ISD.\n- Jose De Escandon Elementary School\n- Irene M Garcia Middle School\n- Palmview High School\n','\n',char(10)),NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/communities/rectUf4cPjgY0GEcZ/PpGoKTlcjbs7ldHTc4nSeCtPVAfXq-cXvDefJFS7kY8',NULL,'https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/communities/rectUf4cPjgY0GEcZ/eEQ_UQUIo9oGSDASzSbC1iSAQ9hIb--HKkgHJnLflHE',NULL,'https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/communities/rectUf4cPjgY0GEcZ/lfIrBao1z465Y2F_SX5llr6682qxmVxkwo6NSbImNYI',NULL,NULL,'https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/communities/rectUf4cPjgY0GEcZ/fIBi9gK81SaxY-Bncy85OWhs0Td_ecQa2jbOPox72Ik',NULL,NULL,NULL,'https://player.vimeo.com/video/1003383781','956-275-8069','Monday - Saturday: 9:30am to 6:30pm Sunday: 12pm to 6 pm','https://www.esperanzahomes.com/new-homes/tx/mission/bentsen-palm-master-planned-community/12092/#request-a-tour','https://www.esperanzahomes.com/financing/',NULL,'https://esperanzahomes.lotvue.com/mpc_level/Bentsen%20Palm',NULL,NULL,NULL,'recXEfaDLyZ0ibeUt','2026-05-31T01:05:16.826Z','2026-05-31T01:05:16.826Z',NULL,'https://esperanza-pdf.round-base-ed8c.workers.dev/pdf/community/bentsen-palm-master-planned-community');
