INSERT INTO "cities" ("id","community_count","move_in_homes_count","floor_plans_count","city_name","slug","state","status","map_latitude","map_longitude","hero_image_url","hero_description","national_recognition","incentive","city_copy_blocks_json","city_venue_blocks_json","created_at","updated_at","custom_fields","published","coming_soon") VALUES('rectswj3LFp5lwPKu',2,29,11,'Brownsville','brownsville','TX','Active',25.9017,-97.4975,'https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/cities/rectswj3LFp5lwPKu/nzXbMMSO_hUcHo0Xr7pWR6FrlU0UdVhti7RiPznBLgI','The City of Brownsville is the largest city in the Rio Grande Valley with a population of nearly 200,000! Brownsville ranks No. 87 out of 150 according to the U.S. News & World Report. Brownsville is recognized for its affordability, desirability, strong job market and high quality of life.','Brownsville ranks No. 87 out of 150 according to the U.S. News & World Report, recognized for its affordability, desirability, strong job market and high quality of life.',NULL,'{"homes_heading":"Our Homes in Brownsville","homes_description":"Esperanza Homes offers beautifully crafted, energy-efficient homes in Brownsville, strategically located for easy access to coastal escapes, major employers and nearby cities across the Rio Grande Valley. With the E-Difference—E-Connected, E-Efficient, E-Simplicity, and E-Customization—we make homeownership more convenient, sustainable and tailored to your lifestyle.","live_in_heading":"Live in Brownsville, Texas","live_in_description":"Find your home in Palo Alto Groves, a community offering convenience and a prime location near everything Brownsville has to offer.","live_in_image":"https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/cities/rectswj3LFp5lwPKu/BrownsvilleRelax_1.jpg","image_0":"https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/cities/rectswj3LFp5lwPKu/Capture-2026-05-29-003118.png","section_1_title":"A Celebration of Culture and Heritage","section_1_description":"Brownsville has numerous galleries, theaters and museums. The city also hosts several annual festivals, such as the Charro Days Fiesta and the Brownsville Latin Jazz Festival, that celebrate its unique cultural heritage and brings together people from all walks of life.","section_1_image":"https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/cities/rectswj3LFp5lwPKu/BrownsvilleContent3_1.jpg","section_1a_image":"https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/cities/rectswj3LFp5lwPKu/BrownsvilleContent5_1.jpg","section_2_title":"Outdoor Lifestyle","section_2_description":"One of the city''s biggest draws is its proximity to the Gulf of America, where visitors can enjoy miles of pristine beaches, warm waters, and a host of outdoor activities, including fishing, kayaking, and birdwatching. Brownsville is also home to several stunning nature reserves, such as the Sabal Palm Sanctuary and the Palo Alto Battlefield National Historical Park.","section_2_image":"https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/cities/rectswj3LFp5lwPKu/SsT_qNdlvxOKl3o_b7vNiw9HfaDNP0LOAOq46gQfPrU","section_3_title":"Life in Brownsville, Texas","section_3_description":"Brownsville has great shopping, dining and entertainment options. Read on to discover a few of our favorites.","section_3_image":"https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/cities/rectswj3LFp5lwPKu/OzsPTAF7x4NS15cK37dNYTxWjORqmX8ZVEt-xpEUMvQ","pillar_1_title":"Strategic Location & Economic Growth","pillar_1_description":"As the largest city in the Rio Grande Valley, Brownsville offers a thriving economy, proximity to the Port of Brownsville, and emerging opportunities with SpaceX.","pillar_2_title":"Rich Culture & Heritage","pillar_2_description":"With a deep historical heritage, vibrant festivals, and a strong sense of community, Brownsville is a welcoming place to call home.","pillar_3_title":"More Home for Your Money","pillar_3_description":"Ranked among the best places to live, Brownsville offers a high quality of life, job opportunities, and a dynamic local food scene.","pillar_4_title":"Outdoor and Coastal Lifestyle","pillar_4_description":"Close to the Gulf of Mexico, Brownsville provides access to beautiful beaches, nature reserves, and year-round outdoor activities."}','{"eat_venues":"[Experience the Taco Trail](https://visitbtx.com/tacotrail/)\n[Bubba''s 33](https://www.bubbas33.com/)\n[Jolie Petite](https://joliepetitebtx.com/)\n","eat_image":"https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/cities/rectswj3LFp5lwPKu/BrownsvilleEat.jpg","shop_venues":"[Sunrise Mall](https://www.sunrisemalltx.com/)\n[JZD](https://shopjzd.com/)\n","shop_image":"https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/cities/rectswj3LFp5lwPKu/BrownsvilleShop2_1.jpg","play_venues":"[SpaceX](https://visitbtx.com/spacex/)\n[Gladys Porter Zoo](https://visitbtx.com/a-day-in-the-zoo-brownsville-texas/)\n[Brownsville Museum of Fine Art](https://mitteculturaldistrict.org/brownsville-museum-of-fine-art/)\n[Historic Brownsville Museum](https://mitteculturaldistrict.org/historic-brownsville-museum/)\n[Charro Days Fiesta](https://visitbtx.com/charrodaysfestival/)\n[Brownsville Latin Jazz Festival](https://brosoperformingarts.org/latin-jazz-festival)\n","play_image":"https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/cities/rectswj3LFp5lwPKu/BrownsvilleSee_1.jpg","relax_venues":"[Sabal Palm Sanctuary](https://www.sabalpalmsanctuary.org/)\n[Palo Alto Battlefield National Historical Park](https://www.nps.gov/paal/index.htm)\n[South Padre Island](https://www.sopadre.com/)\n","relax_image":"https://pub-9c9bfee574a54b62b2623e361b3ad305.r2.dev/cities/rectswj3LFp5lwPKu/BrownsvilleRelax_1.jpg"}','2026-05-31T01:05:16.822Z','2026-05-31T02:25:41.182Z',NULL,1,0);
