ln/presidio','https://my.matterport.com/show/?m=srBMZXXUBDE',NULL,'https://esperanza-pdf.round-base-ed8c.workers.dev/pdf/floorplan/presidio','https://media.esperanzahomes.com/153/2025/3/25/Presidio_272025.pdf',110.33,186.33,76,'Wolf Creek, El Eden',2,'recup9XQCLfyCFwnb,rec5MNICJCfx5bXLO,recRgNPBvA4udkgqN,recwPUhN8MI9lm5K9,recKut2sCg1hsN6qj,recHKimnzJVBwc9wp,reclgURVHnWzfnWOg',NULL,'2026-05-31T01:05:16.826Z','2026-05-31T20:12:00.806Z',NULL,0);
