INSERT INTO "testimonials" ("id","person_name","slug","date_posted","testimonial_text","move_in_year","status","image_url","floor_plan_id","floor_plan_name","floor_plan_image","community_id","community_name","town","created_at","updated_at","custom_fields","published") VALUES('recxl4fOW2R9Pn9ru','Lidia Fonseca',NULL,NULL,'It''s not the first time we''ve owned a home, but it''s the first time we''ve built it, so we really didn''t know what we were getting into. The experience was great with Sam until we got into the actual building phase and then started working with Alex, who was our superintendent, who did a great job with us as well. The reason why we even got there is because of the community feeling and the fact that it was just great, I think, for young families. Once we knew that this would be a great area for our kids to be in and we saw how happy they were, we wanted our family to experience that too.','2020',NULL,NULL,'recqtHpGxguWdzlRp','Francisco I',NULL,NULL,NULL,NULL,'2026-05-31T01:05:24.835Z','2026-05-31T01:05:24.835Z',NULL,1);
