INSERT INTO "audit_log" ("id","entity","entity_id","field","action","old_value","new_value","actor","at") VALUES(50,'promotions','recPB3vLbSccQtv1R','copy','update',NULL,replace(replace('Start this new season in your dream home with these exclusive savings! Buy one of our select move-in-ready homes and enjoy a 4.99% 30-year fixed interest rate on select homes.\r\n\r\nPromotional offers are limited and subject to change. Restrictions and Terms Apply. Select Homes and Communities Only.*\r\n\r\nOffer is available for all customers using Stonewood Home Lending.*','\r',char(13)),'\n',char(10)),'matt@hazard.house','2026-06-05T02:56:47.521Z');
